entries[413525] = { ["name"] = "Sande der Zeit", ["text"] = "100 Meter Reichweite\nSofort\n' Eruption ' [ Frühlingstraum : oder ' Smaragdblüte ' ] erhöht die Dauer Eurer aktiven Effekte von 'Schwarzmacht' um 1 Sek.\n\nEure ermächtigten Zauber erhöhen die Dauer Eurer aktiven Effekte von 'Schwarzmacht' um 2 Sek.\n\n[ Atem der Äonen : ' Atem der Äonen ' / ' Tiefer Atem '] erhöht die Dauer Eurer aktiven Effekte von 'Schwarzmacht' um 5 Sek.\n\nDieser Effekt kann kritisch treffen und erhöht die Dauer von 'Schwarzmacht' dann um zusätzlich 50%." }
entries[413529] = { ["name"] = "Bereinigen", ["text"] = "50 Meter Reichweite\nWirken in 3 sek. 5 sek. Abklingzeit\nEntfesselt Zeitenergie in die Richtung eines anvisierten Spielercharakters und fügt Spielercharakteren in einem frontalen kegelförmigen Bereich 7273348 Arkanschaden zu.\n\nDiese Magie löst außerdem Zeitraketen aus, die Spielercharakteren innerhalb von 4 Metern um jeden Einschlagsort 3636674 Arkanschaden zufügen." }
