entries[413539] = { ["name"] = "Traumfaden", ["text"] = "100 Meter Reichweite\nSofort\nZiele werden an die ' Grüne Matrix ' gebunden, wodurch sie 75%. weniger Schaden durch Nymue erleiden.\n\nAußerdem erleidet das Ziel pro Sekunde 3 Naturschaden und seine Bewegungsgeschwindigkeit ist um 50% verringert, solange es sich innerhalb von 3 Metern um den Faden befindet. Dieser Effekt ist stapelbar." }
