entries[413546] = { ["name"] = "Entzündendes Brüllen", ["text"] = "200 Meter Reichweite\nSofort\nMagmorax brüllt, was allen Spielercharakteren beim Einschlag 167127 Feuerschaden und zusätzlich alle 1 Sek. 4029 Feuerschaden zufügt. Dieser Effekt ist stapelbar.\n\nEntlässt zusätzlich mehrfach ' Lavaauswurf ' in die Kammer." }
