entries[413738] = { ["name"] = "Nerubischer Willensbrecher", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nKampfzerrissene Fetzen (80), Sternrubin (4), Eisenweberseide (20), Essenz des Untodes (12), Arkanitbarren (8)\nEntdeckung:\nNaxxramas\n\nNerubischer Willensbrecher\nWird beim Anlegen gebunden\nDistanz Armbrust\n6 - 10 Schaden Geschwindigkeit 3.00\n(2.7 Schaden pro Sekunde)\n+4 Beweglichkeit\nErhöht Eure kritische Trefferwertung um + 7.\nHaltbarkeit 120 / 120\n25" }
entries[413739] = { ["name"] = "Klinge der unheiligen Kraft", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nKampfzerrissene Fetzen (80), Arkanitbarren (20), Goldbarren (40), Goldene Perle (4), Essenz des Untodes (20)\nEntdeckung:\nNaxxramas\n\nKlinge der unheiligen Kraft\nWird beim Anlegen gebunden\nZweihändig Schwert\n7 - 12 Schaden Geschwindigkeit 3.60\n(2.6 Schaden pro Sekunde)\n+4 Stärke\n+2 Ausdauer\nHaltbarkeit 120 / 120\n25" }
entries[413740] = { ["name"] = "Knochenspalteraxt", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nKampfzerrissene Fetzen (40), Großer Opal (16), Arkanitbarren (8), Thoriumbarren (60), Essenz des Untodes (8)\nEntdeckung:\nNaxxramas\n\nKnochenspalteraxt\nWird beim Anlegen gebunden\nEinzigartig anlegbarEinhändig Axt\n3 - 7 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\n+2 [Beweglichkeit oder Stärke] Erhöht Eure kritische Trefferwertung um + 3.\nHaltbarkeit 110 / 110\n25" }
entries[413741] = { ["name"] = "Der Seuchenspucker", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nKampfzerrissene Fetzen (60), Arkanitbarren (16), Azerothischer Diamant (12), Makelloser schwarzer Diamant (4), Verzaubertes Leder (8), Essenz des Untodes (24)\nEntdeckung:\nNaxxramas\n\nDer Seuchenspucker\nWird beim Anlegen gebunden\nSchildhand Schild\n42 Rüstung\n+2 Stärke\n+6 Intelligenz\n+3 Ausdauer\n+ 2 Ausweichen\nHaltbarkeit 120 / 120\n25" }
entries[413742] = { ["name"] = "Armschienen der Rache", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nKampfzerrissene Fetzen (15), Thoriumbarren (30), Goldbarren (6), Großer Opal (2), Arkanitbarren (6)\nEntdeckung:\nNaxxramas\n\nArmschienen der Rache\nWird beim Anlegen gebunden\nHandgelenk Platte\n7 Rüstung\n+3 [Stärke oder Intelligenz]+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nHaltbarkeit 55 / 55\n25" }
