entries[414145] = { ["name"] = "Sturmschnappen", ["text"] = "45 Meter Reichweite\nWirken in 3.5 sek.\nReißt einem Gegner brutal die Luft aus den Lungen und zieht ihn zum Zaubernden. Befriedet das Ziel und bringt es zum Schweigen, wodurch es 3 Sek. lang nicht angreifen oder Zauber wirken kann." }
