entries[414177] = { ["name"] = "Kataklysmische Auslöschung", ["text"] = "Sofort\nIridikron entfesselt eine kataklysmische Explosion, die allen Spielercharakteren 1212224691 Naturschaden zufügt. Dieser Schaden kann nicht verhindert werden.\n\nBei der Vorbereitung seines Angriffs fügt er allen Spielercharakteren alle 1.5 Sek. 1818337 Naturschaden zu.\n\nIridikron verliert Energie, wenn er Schaden erleidet, und wenn seine Energie auf 0 fällt, versagt diese Fähigkeit. Chromie wirkt ' Zeitlinientranszendenz ', um ihre Verbündeten zu unterstützen." }
entries[414178] = { ["name"] = "Zeitlinientranszendenz", ["text"] = "Unbegrenzte Reichweite\nSofort\nChromie erschafft eine Zeitverzerrungsblase, die Spielercharakteren ihr maximales zukünftiges Potenzial gewährt.\n\nErhöht den verursachten Schaden um 100%, das Tempo um 100%, die Abklingzeitrate um 100% und die Ressourcenregenerationsrate um 100.\n\nChromie kann dies nur einmal tun, ohne eine dauerhafte Konvergenz der Zeitlinien zu riskieren." }
entries[414181] = { ["name"] = "Annuna", ["text"] = "Sofort\nErlernt, wie man Annuna beschwört." }
