entries[414184] = { ["name"] = "Kataklysmische Auslöschung", ["text"] = "Unbegrenzte Reichweite\nWirken in 30 sek.\nIridikron entfesselt eine kataklysmische Explosion, die allen Spielercharakteren 1212224691 Naturschaden zufügt. Dieser Schaden kann nicht verhindert werden.\n\nBei der Vorbereitung seines Angriffs fügt er allen Spielercharakteren alle 1.5 Sek. 1818337 Naturschaden zu.\n\nIridikron verliert Energie, wenn er Schaden erleidet, und wenn seine Energie auf 0 fällt, versagt diese Fähigkeit. Chromie wirkt ' Zeitlinientranszendenz ', um ihre Verbündeten zu unterstützen." }
entries[414186] = { ["name"] = "Lohe", ["text"] = "Sofort\nFyrakk umgibt Spielercharaktere mit Flammen, die nach 4 Sek. explodieren und allen Spielercharakteren im Effektbereich 348114 Schattenflammenschaden zufügen." }
